const response = $input.first().json;
const api = response.body ?? response;
const product = api.product ?? {};
const raw = product.nutriments ?? {};

const readNumber = (value) => {
  if (value === null || value === undefined || value === '') return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
};

const measurements = {
  sugar: readNumber(raw.sugars_100g),
  salt: readNumber(raw.salt_100g),
  fat: readNumber(raw.fat_100g),
};
const available = Object.values(measurements).filter((value) => value !== null).length;
const allMeasurementsPresent = available === 3;
const grade = String(product.nutriscore_grade ?? '').trim().toLowerCase();
const validGrade = ['a', 'b', 'c', 'd', 'e'].includes(grade);

const semaphore = {
  sugar: measurements.sugar === null
    ? 'sin_dato'
    : measurements.sugar < 5 ? 'bajo' : measurements.sugar <= 22.5 ? 'medio' : 'alto',
  salt: measurements.salt === null
    ? 'sin_dato'
    : measurements.salt > 1.5 ? 'alto' : 'bajo',
  fat: measurements.fat === null
    ? 'sin_dato'
    : measurements.fat > 17.5 ? 'alto' : 'bajo',
};
const highCount = Object.values(semaphore).filter((level) => level === 'alto').length;

const rank = { saludable: 0, moderado: 1, 'no saludable': 2 };
const gradeVerdict = validGrade
  ? ({ a: 'saludable', b: 'saludable', c: 'moderado', d: 'no saludable', e: 'no saludable' })[grade]
  : null;
const semaphoreVerdict = allMeasurementsPresent
  ? (highCount === 0 ? 'saludable' : highCount === 1 ? 'moderado' : 'no saludable')
  : null;
const sufficientData = available > 0 && (validGrade || allMeasurementsPresent);
const readings = [gradeVerdict, semaphoreVerdict].filter(Boolean);
const verdict = sufficientData
  ? readings.reduce((worst, current) => rank[current] > rank[worst] ? current : worst)
  : null;

const marker = (level) => ({ bajo: '🟢', medio: '🟡', alto: '🔴', sin_dato: '⚪' })[level];
const energy = readNumber(raw['energy-kcal_100g']);
const headline = verdict === 'saludable'
  ? 'Una buena opción para el día a día'
  : verdict === 'moderado'
    ? 'Mejor para disfrutar con moderación'
    : verdict === 'no saludable'
      ? 'Mejor dejarlo para un gusto ocasional'
      : 'No hay datos suficientes para valorarlo';

return [{ json: {
  barcode: String($('01 - Webhook SnackCheck').first().json.query.barcode).trim(),
  productName: product.product_name || 'Producto sin nombre',
  brands: product.brands || null,
  nutriscoreGrade: validGrade ? grade : null,
  energyKcal100g: energy,
  measurements,
  semaphore: Object.fromEntries(Object.entries(semaphore).map(([key, level]) => [key, {
    level, marker: marker(level), value: measurements[key], unit: 'g/100 g',
  }])),
  concernScore: available > 0 ? highCount : null,
  concernScoreComplete: allMeasurementsPresent,
  missingMeasurements: Object.entries(measurements).filter(([, value]) => value === null).map(([key]) => key),
  gradeVerdict, semaphoreVerdict, sufficientData, verdict, headline,
} }];

